{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "བྲམ་ཟེ་ས་ར་ཧས།",
      "head": "མ་བཅོས་མ་བཅོས་བློ་མ་བཅོས།",
      "tail": "བཅོས་མའི་ཆོས་ཀྱིས་འཚང་མི་རྒྱ། །"
    },
    {
      "label": "QUOTE",
      "frame": "བང་མཛོད་ལས།",
      "head": "སེམས་མ་བཅོས་ན་གསལ། །",
      "tail": "ཆུ་མ་རྙོགས་ན་དྭངས། །"
    },
    {
      "label": "QUOTE",
      "frame": "སཾ་ཊི་ལས།",
      "head": "ཡེ་ཤེས་ཉོན་མོངས་མཉམ་པར་འགྲོ །",
      "tail": "ཡེ་ཤེས་ལྔ་དང་སངས་རྒྱས་ལྔ། །"
    },
    {
      "label": "QUOTE",
      "frame": "སཾ་ཊི་ལས།",
      "head": "ཆགས་པས་ཆགས་པ་འདག་པར་བྱེད། །",
      "tail": "རྡོ་རྗེ་འཛིན་སོགས་ཐམས་ཅད་སྦྱོང༌། །"
    },
    {
      "label": "QUOTE",
      "frame": "བྲམ་ཟེ་ཆེན་པོས།",
      "head": "ཇི་ལྟར་རྒྱ་མཚོ་བ་ཚྭ་ཅན་གྱི་ཆུ། །",
      "tail": "ཡུལ་གྱི་དུག་ཀྱང་བདུད་རྩིར་འགྱུར་བ་ཡིན། །"
    },
    {
      "label": "QUOTE",
      "frame": "ནཱ་རོ་པས།",
      "head": "ནད་དང་གདོན་གྱི་བར་གཅོད་ཀྱང༌། །",
      "tail": "ནད་གདོན་འབྱུང་བར་མི་འགྱུར་རོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་བཙུན་གྱིས།",
      "head": "འདྲེར་སྣང་འདྲེར་རྟོག་འདྲེར་འཛིན་གསུམ། །",
      "tail": "འདྲེ་རང་རྒྱུད་འཛིན་པ་རྣལ་འབྱོར་འཁྲུལ། །"
    },
    {
      "label": "QUOTE",
      "frame": "མདོ་དྲན་པ་ཉེར་གཞག་ལས།",
      "head": "མེ་ནི་གྲང་བར་འགྱུར་ཡང་སྲིད། །",
      "tail": "ལས་ཀྱི་རྣམ་སྨིན་བསླུ་མི་སྲིད། །"
    },
    {
      "label": "QUOTE",
      "head": "ལུས་ཅན་རྣམས་ཀྱི་ལས་རྣམས་ནི། །",
      "tail": "འབྲས་བུ་ཉིད་དུ་སོ་སོར་སྨིན། །"
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་ཕག་མོ་གྲུབ་པས།",
      "head": "སྙིང་ནས་ཆོས་ཤིག་གོ་གྱུར་ན། །",
      "tail": "སྡུག་བསྔལ་ཐམས་ཅད་བདེ་ཆེན་ཡིན། །"
    },
    {
      "label": "QUOTE",
      "frame": "མགུར་ལས།",
      "head": "སྟོང་ཉིད་སྙིང་རྗེ་དབྱེར་མེད་པ། །",
      "tail": "དགེ་འདུན་གྱི་ནི་བསྟན་པ་ཡིན། །"
    },
    {
      "label": "QUOTE",
      "frame": "རྒྱལ་བ་རྒོད་ཚང་པས།",
      "head": "གཞན་ལ་མི་སྲིད་པ་ཞིག་ང་ལ་སྲིད་པར་གདའ་སྟེ། གཞན་རྣམས་སྐྱིད་ཙ་ན་རྒོད་བྲོ། སྡུག་ན་ངུ་བྲོ་བ་ཡིན། ང་ལ་སྐྱིད་ཙ་ན་ངུ་བྲོ། སྡུག་ན་རྒོད་བྲོ་བར་འདུག །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "རྣམ་རྟོག་སྐྱེ་བ་དང༌། འགགས་པས་ཀྱང་སྐྱེ་འཆི་མཚོན་ཏེ། གཉིད་དུ་འགྲོ་བ་ལ་འཆི་བ་དང༌། གཉིད་སད་པ་སྐྱེ་བ་ཡིན་ལ། དོན་དུ་རྣམ་རྟོག་ཕྲ་རགས་ཀྱི་ཁྱད་པར་མ་གཏོགས། རྣམ་རྟོག་ལས་མ་འདས་པས་ན། ན་ནའང་རྣམ་པར་རྟོག་པ་ན། འཆི་ནའང་རྣམ་རྟོག་པ་འཆི་བ་ཡིན། དེས་ན་སོ་སྐྱེལམ་དུ་མུ་ཞུགས་པ་རྣམས་ལ།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "རྣམ་རྟོག་མ་རིག་ཆེན་པོ་འདི། །འཁོར་བའི་རྒྱ་མཚོར་ལྟུང་བྱེད་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "རྣལ་འབྱོར་པ་རྣམས་ལ། འཆི་བ་ཞེས་བྱ་རྣམ་རྟོག་སྟེ། །མཁའ་སྤྱོད་གནས་སུ་ཁྲིད་པར་བྱེད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཨོ་རྒྱན་རིན་པོ་ཆེས།",
      "head": "རྣལ་འབྱོར་པ་རབ་ཆོས་སྐུའི་འཕོ་བ་ནི། འཕོ་བྱའི་ཡུལ་དང་འཕོ་བྱེད་གཉིས་སུ་མུ་གྲུབ་པའི་རང་བཞིན་རྫོགས་པ་ཆེན་པོའི་ངང་དུ་གནས་པ་ནི་འཕོ་བའི་མཐར་ཐུག་གོ །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྒྱུད་ལས།",
      "head": "འཆི་བ་ཞེས་བྱ་རྣམ་རྟོག་སྟེ། །",
      "tail": "མཁའ་སྤྱོད་གནས་སུ་ཁྲིད་པར་བྱེད། །"
    },
    {
      "label": "QUOTE",
      "head": "སྐད་ཅིག་གཅིག་གིས་བྱེ་བྲག་ཕྱེད། །",
      "tail": "སྐད་ཅིག་གཅིག་གིས་རྫོགས་སངས་རྒྱས། །"
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་སྒམ་པོ་པས།",
      "head": "རྣམ་རྟོག་གཅིག་ནས་གཅིག་འགྲོ་བ། །",
      "tail": "སེམས་ལ་སྐྱེ་འཆི་མེད་པ་ལ། །དེ་ལ་འཆི་རྒྱུ་ག་ལ་ཡོད། །"
    }
  ]
}
